import{_ as l,l as s,o as e,c as o,v as r,p,x as t,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"可观测三支柱","description":"","frontmatter":{"title":"可观测三支柱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/observability-pillars.md","filePath":"cs/observability-pillars.md","lastUpdated":1789023840000}'),h={name:"cs/observability-pillars.md"};function _(E,a,m,u,A,f){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="可观测三支柱" tabindex="-1">可观测三支柱 <a class="header-anchor" href="#可观测三支柱" aria-label="Permalink to &quot;可观测三支柱&quot;">​</a></h1><div class="epigraph"><p>指标告诉你「有多糟、多少」，日志告诉你「这条记录说什么」，追踪告诉你「这次请求走了哪」。三根柱子互补，不是三个品牌。</p><footer>—— 据 Dapper；Google SRE 书中的监控；OpenTelemetry 对 traces/metrics/logs 的划分整理</footer></div><p>上一课<a href="/cs/distributed-tracing">追踪</a>只覆盖采样到的请求树。缺口是<strong>系统级与事件级</strong>：QPS、错误率、饱和度没有 trace 也对；审计与异常细节在日志里。本课钉三者分工与关联（同一 trace id）。后课混沌工程用它们当实验的测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指标：聚合、便宜、低基数；高基数会爆炸。日志：高基数、贵、要检索；无结构则不可聚合。追踪：中基数、看一次调用的边。缺口：只用日志 grep 无法得 SLO；只用指标不知道是哪次用户；只用追踪看不见未采样与非请求路径（磁盘满）。</p><p>关联：日志打 trace id；指标用 exemplar 挂 trace；告警先指标后追踪再日志。</p><p><span class="marginnote">「三支柱」是教学口号。事件（span 事件）与剖析（profile）常被列为第四、第五，本课点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SLO：用指标定义错误预算。排障：告警 → 相关服务红图 → 一条坏 trace → 该 span 时间戳附近的日志。基数预算：user id 进日志或追踪属性，不进无限标签的指标。</p>',9)),(e(),p(c,null,{default:t(()=>[n(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALERT%5B%22%E6%8C%87%E6%A0%87%E5%91%8A%E8%AD%A6%22%5D%20--%3E%20TR%5B%22%E6%8C%91%E4%B8%80%E6%9D%A1%E8%BF%BD%E8%B8%AA%22%5D%0A%20%20TR%20--%3E%20LOG%5B%22%E5%B8%A6%20id%20%E7%9A%84%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20FIX%5B%22%E5%AE%9A%E4%BD%8D%E4%BB%A3%E7%A0%81%20%2F%20%E4%BE%9D%E8%B5%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要用追踪后端当日志仓库，也不要把每条日志当 metric 递增。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>采样不一致：指标说 1% 错误，追踪只采到成功树，会误判。错误强制采样是修补。时钟：日志时间戳墙钟漂移，关联仍靠 id 不是靠时间对齐。</p><p>本课不写 Prometheus 与 Loki 的全部算子。也不把可观测写成安全 SIEM 全文。</p><p>与<a href="/cs/failure-models">故障模型</a>：观察系统自己会故障。监控分区时你看见的「全绿」可能是假的——要独立通道与合成探测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入混沌实验设计（下一课）。不写日志合规保留年限。后课默认：SLO 用指标；因果路径用追踪；细节用结构化日志加 id。混沌工程把故障注入，用这三根柱子读结果。</p><p>口号去掉之后，留下的是三种不同聚合粒度的数据。缺一种就有一类问题看不见。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指标聚合、日志细节、追踪请求图。</li><li>用 id 关联；控制指标基数。</li><li>观察平面自己也会分区，要合成探测。</li><li>出处：Dapper；SRE 监控实践。</li></ul>',10))])}const B=l(h,[["render",_]]);export{T as __pageData,B as default};
